import{_ as s,l as o,o as e,c as n,v as r,p as d,x as t,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"浮点加法器","description":"","frontmatter":{"title":"浮点加法器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fp-adder.md","filePath":"cs/fp-adder.md","lastUpdated":1789023840000}'),E={name:"cs/fp-adder.md"};function h(_,a,A,m,f,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="浮点加法器" tabindex="-1">浮点加法器 <a class="header-anchor" href="#浮点加法器" aria-label="Permalink to &quot;浮点加法器&quot;">​</a></h1><div class="epigraph"><p>对阶把小数点对齐，相加之后可能要右移一位或左移许多位；路径深度来自移位与前导零，而不是再造一种 IEEE 位型。</p><footer>—— 据 IEEE Std 754-2008；Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/newton-division">上一课</a>把除收成迭代乘，并预告浮点还要对阶与舍入。<a href="/cs/ieee-754">IEEE 754</a> 与<a href="/cs/rounding-modes">舍入模式</a>已钉位型和往哪边靠。缺口是电路：<strong>两个规格化数相加</strong>要经过哪几级组合（或流水），整数 <a href="/cs/adder-cla">CLA</a> 只出现在尾数对齐之后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\((\\pm m_1 2^{e_1})+(\\pm m_2 2^{e_2})\\)。先比较指数，把较小的尾数右移 \\(|e_1-e_2|\\) 位（对阶），再按符号决定尾数加或减。和可能 \\(\\in[1,4)\\) 或对消到远小于 1。缺口不是再解释隐藏位，而是数据通路：指数差 → 移位器 → 尾数加减 → 规格化移位 → 舍入。近路径（指数接近、有效减法）与远路径（指数差大或有效加法）可以拆成两条以切延迟——本课点名，不把每级流水线寄存器画完。</p><h3 id="对阶不是「先都变成定点再加」" tabindex="-1">对阶不是「先都变成定点再加」 <a class="header-anchor" href="#对阶不是「先都变成定点再加」" aria-label="Permalink to &quot;对阶不是「先都变成定点再加」&quot;">​</a></h3><p>右移丢掉的位要进 sticky/guard/round，否则<a href="/cs/rounding-modes">舍入</a>少信息。把浮点加当成「转定点、整数加、再转回」，会丢掉 GRS 位，也无法处理指数溢出到无穷。非规格化操作数把隐藏位改成 0，移位规则不同，本课承认，细节留给<a href="/cs/lzc-normalize">前导零</a>。</p><p><span class="marginnote">Patterson/Hennessy 用对阶–加–规格化三框图教学。Harris 把移位器与加法器画实。754 的加法是格式上的正确舍入运算，硬件路径必须保留舍入所需的额外比特。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>指数比较与差。2. 对齐移位（桶形移位 + sticky OR）。3. 有效加/减（<a href="/cs/adder-cla">CLA</a>）。4. 若最高位进位则右规 1 位并指数加 1；若前导零则左规。5. 按模式舍入，可能再进位导致二次规格化。符号：有效减时由幅度大的那个决定。</li></ol>',10)),(e(),d(p,null,{default:t(()=>[c(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22%E4%B8%A4%E6%93%8D%E4%BD%9C%E6%95%B0%22%5D%20--%3E%20ALIGN%5B%22%E5%AF%B9%E9%98%B6%E7%A7%BB%E4%BD%8D%22%5D%0A%20%20ALIGN%20--%3E%20ADD%5B%22%E5%B0%BE%E6%95%B0%E5%8A%A0%E5%87%8F%22%5D%0A%20%20ADD%20--%3E%20NORM%5B%22%E8%A7%84%E6%A0%BC%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20RND%5B%22%E8%88%8D%E5%85%A5%22%5D%0A%20%20RND%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B9%98%E4%B8%8E%20FMA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>指数全 1 / 全 0 的特殊值走旁路：NaN 传播、无穷规则，下一课异常旗标再钉检测点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 FMA 把「乘完再加」熔成一次舍入，加法器会多吃一个乘积宽度的对齐。本课的独立加法器仍是 ABI 里 <code>fadd</code> 的语义核。流水线切在移位与加法之间，是微结构，不改变 754 函数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现十进制 754，不把 SIMD 打包浮点加写成向量通路——那是后课 ISA 对照。也不把「训练用的混合精度加法」写进组成；本栏是比特到系统。</p><p>后课默认：浮点加 = 对阶 + 尾数加减 + 规格化 + 舍入；整数 CLA 只作用于对齐后的尾数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>位型已在 754；本课是加法数据通路。</li><li>对阶移位保留 GRS；规格化处理进位与对消。</li><li>近/远路径是延迟切分，不是两种语义。</li><li>出处：IEEE 754-2008；Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const C=s(E,[["render",h]]);export{D as __pageData,C as default};
